function(props) {
  const prediction = props.data;

  const statusColors = {
    succeeded: '#dcfce7',
    processing: '#e0f2fe',
    failed: '#fee2e2',
    starting: '#fef3c7',
    canceled: '#e2e8f0'
  };

  const styles = {
    card: {
      backgroundColor: '#ffffff',
      borderRadius: '8px',
      border: '1px solid #e2e8f0',
      padding: '16px',
      marginBottom: '12px',
      width: '100%',
      boxSizing: 'border-box'
    },
    header: {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      marginBottom: '12px'
    },
    statusBadge: {
      padding: '4px 8px',
      borderRadius: '20px',
      fontSize: '12px',
      fontWeight: '500',
      textTransform: 'capitalize'
    },
    grid: {
      display: 'grid',
      gridTemplateColumns: prediction.artefacts_urls?.length === 1 
        ? '1fr' 
        : 'repeat(auto-fit, minmax(200px, 1fr))',
      gap: '12px',
      marginTop: '16px'
    },
    mediaItem: {
      position: 'relative',
      borderRadius: '6px',
      overflow: 'hidden',
      background: '#f1f5f9'
    },
    image: {
      width: '100%',
      height: '200px',
      objectFit: 'cover'
    },
    video: {
      width: '100%',
      height: '200px',
      objectFit: 'cover'
    },
    meta: {
      fontSize: '13px',
      color: '#64748b',
      marginTop: '8px'
    },
    link: {
      color: '#3b82f6',
      textDecoration: 'none',
      ':hover': {
        textDecoration: 'underline'
      }
    }
  };

  return React.createElement('div', { style: styles.card },
    React.createElement('div', { style: styles.header },
      React.createElement('div', null,
        React.createElement('h3', { style: { margin: 0, fontSize: '16px', color: '#1e293b' } }, 'Prediction ', 
          React.createElement('a', {
            href: `https://replicate.com/p/${prediction.id}`,
            style: styles.link,
            target: '_blank',
            rel: 'noopener noreferrer'
          }, prediction.id.slice(0, 8))
        ),
        React.createElement('div', { style: { ...styles.meta, marginTop: '4px' } },
          new Date(prediction.created_at).toLocaleDateString()
        )
      ),
      React.createElement('div', { 
        style: { 
          ...styles.statusBadge,
          backgroundColor: statusColors[prediction.status] || '#e2e8f0',
          color: '#1e293b'
        }
      }, prediction.status)
    ),

    prediction.artefacts_urls && prediction.artefacts_urls.length > 0 &&
      React.createElement('div', { style: styles.grid },
        prediction.artefacts_urls.map((url, index) => {
          const isVideo = url.match(/\.(mp4|mov|webm)$/i);
          return React.createElement('div', { key: index, style: styles.mediaItem },
            isVideo ? 
              React.createElement('video', {
                style: styles.video,
                controls: true,
                src: url
              })
            :
              React.createElement('img', {
                style: styles.image,
                src: url,
                alt: `Prediction output ${index + 1}`
              })
          );
        })
      )
  );
}

function(props) {
  const predictions = props.data.results || [];

  const statusColors = {
    succeeded: '#16a34a',
    processing: '#2563eb',
    failed: '#dc2626',
    starting: '#d97706',
    canceled: '#64748b'
  };

  const styles = {
    container: {
      display: 'grid',
      gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))',
      gap: '16px',
      width: '100%'
    },
    card: {
      backgroundColor: '#ffffff',
      borderRadius: '8px',
      border: '1px solid #e2e8f0',
      padding: '12px',
      transition: 'transform 0.2s',
      ':hover': {
        transform: 'translateY(-2px)'
      }
    },
    thumbnail: {
      width: '100%',
      height: '160px',
      objectFit: 'cover',
      borderRadius: '4px',
      marginBottom: '8px'
    },
    meta: {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center'
    },
    status: {
      fontSize: '12px',
      fontWeight: '500',
      textTransform: 'capitalize'
    },
    date: {
      fontSize: '12px',
      color: '#64748b'
    },
    link: {
      color: '#1e293b',
      textDecoration: 'none',
      ':hover': {
        textDecoration: 'underline'
      }
    }
  };

  return React.createElement('div', { style: styles.container },
    predictions.map(prediction => {
      const firstMedia = prediction.artefacts_urls?.[0];
      return React.createElement('a', {
        key: prediction.id,
        href: `https://replicate.com/p/${prediction.id}`,
        style: styles.link,
        target: '_blank',
        rel: 'noopener noreferrer'
      },
        React.createElement('div', { style: styles.card },
          firstMedia && React.createElement('img', {
            style: styles.thumbnail,
            src: firstMedia,
            alt: 'Prediction output'
          }),
          React.createElement('div', { style: styles.meta },
            React.createElement('span', { 
              style: { 
                ...styles.status,
                color: statusColors[prediction.status] || '#64748b'
              }
            }, prediction.status),
            React.createElement('span', { style: styles.date },
              new Date(prediction.created_at).toLocaleDateString('en-US', {
                month: 'short',
                day: 'numeric'
              })
            )
          )
        )
      );
    })
  );
}
